namespace Kaleido.Eventing;

/// <summary>
/// Correlation and traceability context attached to every process domain event.
/// Populated by the framework from the active <see cref="Kaleido.Observability.KaleidoCorrelationContext"/>
/// and <see cref="KaleidoServiceOptions"/> at event creation time.
/// </summary>
[ExcludeFromCodeCoverage]
public sealed record ProcessEventContext
{
    /// <summary>
    /// The unique identifier of the originating request.
    /// Always populated — generated by the framework if not supplied by the caller via <c>X-Kaleido-Request-Id</c>.
    /// Pass the same value on all service calls in a user action to correlate events across service boundaries.
    /// </summary>
    public required string RequestId { get; init; }

    /// <summary>The service that emitted this event, from <see cref="KaleidoServiceOptions.ServiceName"/>.</summary>
    public required string ServiceName { get; init; }

    /// <summary>
    /// The version of <see cref="ServiceName"/> (<see cref="KaleidoServiceOptions.ServiceVersion"/>); <see langword="null"/>
    /// when the service is unversioned. With several versions publishing to one stream, it tells them apart (#552).
    /// </summary>
    public string? ServiceVersion { get; init; }

    /// <summary>The process instance this event belongs to.</summary>
    public required Guid ProcessId { get; init; }

    /// <summary>
    /// The version of the process state this event describes, per process and processor (#552): a
    /// transition's event (process created, step completed) carries the version its save wrote, plan built
    /// the version it read, and execution completed the version the request ended with.
    /// </summary>
    /// <remarks>
    /// Events are delivered at least once and in no guaranteed order: consumers order a process's events by
    /// this version (events of one request may share it), and a gap in the versions of a process's
    /// transitions means a transition's event has not arrived yet.
    /// </remarks>
    public long ProcessVersion { get; init; }

    /// <summary>The step that was executing when this event was emitted.</summary>
    public required string StepName { get; init; }

    /// <summary>
    /// The stable instance identifier of the service that produced this event.
    /// Always from <see cref="KaleidoServiceOptions.InstanceId"/> — never from an inbound header.
    /// </summary>
    public string? ProcessorInstanceId { get; init; }

    /// <summary>
    /// The processor whose step called this service (<c>X-Kaleido-Calling-Processor</c>).
    /// <see langword="null"/> when the request did not come from another processor's step.
    /// </summary>
    public string? CallingProcessorName { get; init; }

    /// <summary>The step in <see cref="CallingProcessorName"/> that called this service (<c>X-Kaleido-Calling-Step</c>).</summary>
    public string? CallingStepName { get; init; }

    /// <summary>
    /// The authenticated caller of the request that produced this event, as the principal provides it
    /// (<see cref="Kaleido.Observability.KaleidoCaller"/>); <see langword="null"/> for anonymous requests.
    /// A tag only, and personal data: published unclassified - remove it in an <see cref="IKaleidoEventRedactor"/>
    /// where the event stream must not carry it.
    /// </summary>
    public Kaleido.Observability.KaleidoCaller? Caller { get; init; }

    /// <summary>
    /// The application acting for the caller on the hop that produced this event (a calling service or a
    /// front door), from the principal's actor claim - never from headers (ADR 0022). <see langword="null"/>
    /// when the principal names none.
    /// </summary>
    public string? CallerActor { get; init; }

    /// <summary>
    /// The front door the request came through (e.g. <c>mcp</c>), end-to-end (<c>X-Kaleido-Origin</c>).
    /// Informational: an audit hint, never proof - <see cref="CallerActor"/> is the trusted counterpart.
    /// </summary>
    public string? Origin { get; init; }

    /// <summary>The front door's name for what started the request (the MCP tool; <c>X-Kaleido-Origin-Tool</c>), informational.</summary>
    public string? OriginTool { get; init; }
}
